<?php
session_start(); require_once '../conexion.php';
if (!isset($_SESSION['usuario_id']) || $_SESSION['rol'] !== 'admin') { header('Location: ../login.php'); exit; }
$id=isset($_GET['id'])?trim($_GET['id']):''; if($id===''){header('Location: operarios.php?error='.urlencode('Operario inválido.'));exit;}
$stmt=$conexion->prepare("SELECT p.CI AS id,p.usuario AS nombre,p.usuario,o.Estado AS estado FROM Persona p JOIN Operario o ON o.CI=p.CI WHERE p.CI=? AND p.Rol='Operario'"); $stmt->bind_param('s',$id);$stmt->execute();$resultado=$stmt->get_result();if($resultado->num_rows!==1){$stmt->close();header('Location: operarios.php?error='.urlencode('Operario no encontrado.'));exit;}$operario=$resultado->fetch_assoc();$stmt->close();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $nombre=isset($_POST['nombre'])?trim($_POST['nombre']):'';$usuario=isset($_POST['usuario'])?trim($_POST['usuario']):'';$password=isset($_POST['password'])?$_POST['password']:'';$estado=isset($_POST['estado'])?$_POST['estado']:'Activo';
 if($nombre===''||$usuario===''){$error='Nombre y usuario son obligatorios.';}else{
  if($password!==''){$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conexion->prepare("UPDATE Persona SET usuario=?,`contraseña`=? WHERE CI=? AND Rol='Operario'");$stmt->bind_param('sss',$usuario,$hash,$id);$stmt->execute();$stmt->close();}else{$stmt=$conexion->prepare("UPDATE Persona SET usuario=? WHERE CI=? AND Rol='Operario'");$stmt->bind_param('ss',$usuario,$id);$stmt->execute();$stmt->close();}$stmt=$conexion->prepare("UPDATE Operario SET Estado=? WHERE CI=?");$stmt->bind_param('ss',$estado,$id);
  if($stmt->execute()){$stmt->close();header('Location: operarios.php?mensaje='.urlencode('Operario modificado correctamente.'));exit;}$error=($stmt->errno==1062)?'Ese usuario ya existe.':'No se pudo modificar: '.$stmt->error;$stmt->close();
 }
 $operario['nombre']=$nombre;$operario['usuario']=$usuario;$operario['estado']=$estado;
}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Editar operario | Softyle</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="../CSS/sistema.css"></head><body class="sistema-body"><nav class="sistema-navbar"><div class="navbar-brand-sistema"><div class="navbar-logo"><i class="bi bi-box-seam"></i></div><div><strong>SOFTYLE</strong><small>Panel administrativo</small></div></div><a href="operarios.php" class="btn-logout"><i class="bi bi-arrow-left"></i></a></nav><main class="admin-container"><a href="operarios.php" class="volver-link"><i class="bi bi-arrow-left"></i> Volver a operarios</a><section class="dashboard-header"><span class="dashboard-label">PERSONAL</span><h1>Editar operario</h1><p>Modificá los datos del operario.</p></section><?php if($error!==''){?><div class="alert alert-danger"><?php echo htmlspecialchars($error,ENT_QUOTES,'UTF-8');?></div><?php }?><div class="form-sistema-card"><form method="POST"><div class="mb-3"><label class="form-label">Nombre completo</label><input type="text" name="nombre" class="form-control" value="<?php echo htmlspecialchars($operario['nombre'],ENT_QUOTES,'UTF-8');?>" required></div><div class="mb-3"><label class="form-label">Usuario</label><input type="text" name="usuario" class="form-control" value="<?php echo htmlspecialchars($operario['usuario'],ENT_QUOTES,'UTF-8');?>" required></div><div class="mb-3"><label class="form-label">Nueva contraseña <small>(opcional)</small></label><input type="password" name="password" class="form-control"><small class="text-muted">Dejá vacío para conservar la actual.</small></div><div class="mb-4"><label class="form-label">Estado</label><select name="estado" class="form-select"><option value="Activo" <?php if(strtolower($operario['estado'])==='activo'){echo 'selected';}?>>Activo</option><option value="Inactivo" <?php if(strtolower($operario['estado'])!=='activo'){echo 'selected';}?>>Inactivo</option></select></div><button type="submit" class="btn-picking"><i class="bi bi-save"></i> Guardar cambios</button></form></div></main></body></html>
